/**
 * Stellar Drift — the rocks as Blender wrote them (stellar-drift-rock-models.js, generated by
 * scripts/blender/stellar_drift_rocks.py): that the module decodes, that every model is a closed
 * body of about a unit across wound the right way, that its baked shading is in range, that the six
 * designs keep the silhouettes they were made for, that the levels cost what the field budgets for,
 * and that a level merges into one mesh whose every vertex names the design it belongs to.
 */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { STELLAR_DRIFT_ROCK_MODELS as MODELS } from '../../src/themes/stellar-drift/stellar-drift-rock-models.js';
import {
    ICE_DESIGNS, ROCK_DESIGNS, ROCK_LEVELS, rockMesh,
} from '../../src/themes/stellar-drift/stellar-drift-rocks.js';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
const DESIGNS = ['block', 'rubble', 'potato', 'binary', 'splinter', 'slab'];
/** Triangles a model of each level may have: enough to hold its shape, few enough for its count. */
const TRIANGLES = { hero: [900, 1300], boulder: [260, 420], chip: [50, 110] };

function decode(text, Type) {
    const bytes = Uint8Array.from(atob(text), (c) => c.charCodeAt(0));
    return new Type(bytes.buffer);
}

function read(model) {
    const positions = Array.from(decode(model.positions, Int16Array), (v) => v * MODELS.quant);
    return {
        positions,
        normals: Array.from(decode(model.normals, Int8Array), (v) => v / 127),
        shade: Array.from(decode(model.shade, Uint8Array), (v) => v / 255),
        index: Array.from(decode(model.index, Uint16Array)),
        at: (v) => positions.slice(v * 3, v * 3 + 3),
    };
}

const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const mean = (values) => values.reduce((sum, v) => sum + v, 0) / values.length;
/** A shade channel: 0 = ambient occlusion, 1 = crest, 2 = thin. */
const channel = (mesh, k) => mesh.shade.filter((_, i) => i % 3 === k);

const ALL = ROCK_LEVELS.flatMap((level) => MODELS[level].map((model) => [`${level} ${model.design}`, level, model]));

/** A model's extents along its own axes, smallest first. */
function extents(model) {
    const mesh = read(model);
    return [0, 1, 2].map((k) => {
        const values = mesh.positions.filter((_, i) => i % 3 === k);
        return Math.max(...values) - Math.min(...values);
    }).sort((a, b) => a - b);
}

describe('stellar drift rock models', () => {
    it('holds six designs at three levels, three of them ice by nature', () => {
        expect(MODELS.designs).toEqual(DESIGNS);
        expect(ROCK_DESIGNS).toEqual(DESIGNS);
        expect(ROCK_LEVELS).toEqual(['hero', 'boulder', 'chip']);
        ROCK_LEVELS.forEach((level) => expect(MODELS[level].map((m) => m.design)).toEqual(DESIGNS));
        expect([...ICE_DESIGNS].sort()).toEqual(['block', 'rubble', 'splinter']);
        expect(MODELS.quant).toBeGreaterThan(0);
        expect(Object.isFrozen(MODELS)).toBe(true);
    });

    it.each(ALL)('%s decodes to the counts it names, within its level\'s budget', (_name, level, model) => {
        const mesh = read(model);
        expect(mesh.positions).toHaveLength(model.vertexCount * 3);
        expect(mesh.normals).toHaveLength(model.vertexCount * 3);
        expect(mesh.shade).toHaveLength(model.vertexCount * 3);
        expect(mesh.index).toHaveLength(model.triangleCount * 3);
        expect(model.triangleCount).toBeGreaterThanOrEqual(TRIANGLES[level][0]);
        expect(model.triangleCount).toBeLessThanOrEqual(TRIANGLES[level][1]);
        expect([...mesh.positions, ...mesh.normals, ...mesh.shade].every(Number.isFinite)).toBe(true);
        expect(Math.max(...mesh.index)).toBe(model.vertexCount - 1);
        expect(Math.min(...mesh.index)).toBe(0);
        // Every vertex is used: a spare one is dead weight in every rock of the field.
        expect(new Set(mesh.index).size).toBe(model.vertexCount);
    });

    it.each(ALL)('%s is a body about a unit across, centred, wound outward', (_name, _level, model) => {
        const mesh = read(model);
        let far = 0;
        const lo = [Infinity, Infinity, Infinity];
        const hi = [-Infinity, -Infinity, -Infinity];
        for (let v = 0; v < model.vertexCount; v++) {
            const p = mesh.at(v);
            far = Math.max(far, Math.hypot(...p));
            for (let k = 0; k < 3; k++) {
                lo[k] = Math.min(lo[k], p[k]);
                hi[k] = Math.max(hi[k], p[k]);
            }
        }
        // A bounding radius of one: the design's levels share a scale, and one of them reaches it.
        expect(far).toBeLessThanOrEqual(1 + 1e-4);
        expect(far).toBeGreaterThan(0.9);
        const size = hi.map((v, k) => v - lo[k]);
        // Never a needle or a sheet: the thinnest (the slab) still has a body.
        expect(Math.min(...size)).toBeGreaterThan(0.3);
        expect(Math.max(...size)).toBeGreaterThan(1.4);
        // Its middle is near the origin (the tumble turns it about there).
        expect(Math.hypot(...lo.map((v, k) => (v + hi[k]) / 2))).toBeLessThan(0.3);
        // Wound counter-clockwise seen from outside: a positive volume, and no collapsed face.
        let volume = 0;
        let thin = 0;
        for (let t = 0; t < mesh.index.length; t += 3) {
            const [a, b, c] = [mesh.at(mesh.index[t]), mesh.at(mesh.index[t + 1]), mesh.at(mesh.index[t + 2])];
            volume += dot(a, cross(b, c)) / 6;
            if (Math.hypot(...cross(sub(b, a), sub(c, a))) < 1e-7) thin += 1;
        }
        expect(volume).toBeGreaterThan(0.15);
        expect(volume).toBeLessThan((4 / 3) * Math.PI);
        expect(thin).toBe(0);
    });

    it.each(ALL)('%s carries the fine surface\'s normals and shading', (_name, level, model) => {
        const mesh = read(model);
        // Unit normals (eight bits a component), which agree with the faces they shade.
        for (let v = 0; v < model.vertexCount; v++) {
            const n = mesh.normals.slice(v * 3, v * 3 + 3);
            expect(Math.hypot(...n)).toBeGreaterThan(0.9);
            expect(Math.hypot(...n)).toBeLessThan(1.1);
        }
        let agree = 0;
        let corners = 0;
        for (let t = 0; t < mesh.index.length; t += 3) {
            const [ia, ib, ic] = mesh.index.slice(t, t + 3);
            const face = cross(sub(mesh.at(ib), mesh.at(ia)), sub(mesh.at(ic), mesh.at(ia)));
            const length = Math.hypot(...face) || 1;
            for (const v of [ia, ib, ic]) {
                agree += dot(face, mesh.normals.slice(v * 3, v * 3 + 3)) / length;
                corners += 1;
            }
        }
        // (The coarser the level, the further its few faces stand from the surface they were cut from.)
        expect(agree / corners).toBeGreaterThan({ hero: 0.85, boulder: 0.8, chip: 0.65 }[level]);
        const ao = channel(mesh, 0);
        const crest = channel(mesh, 1);
        const thin = channel(mesh, 2);
        // Mostly open to the sky; darker somewhere on the finer levels.
        expect(Math.max(...ao)).toBeGreaterThan(0.9);
        expect(mean(ao)).toBeGreaterThan(0.6);
        expect(Math.max(...crest)).toBeGreaterThan(0.6);
        expect(Math.min(...thin)).toBeGreaterThanOrEqual(0);
        expect(Math.max(...thin)).toBeLessThanOrEqual(1);
        if (level === 'hero') {
            // Crests and crevices both sides of flat (0.5).
            expect(Math.min(...crest)).toBeLessThan(0.45);
            // ...and every design but the clean splinter shades itself somewhere.
            if (model.design !== 'splinter') expect(Math.min(...ao)).toBeLessThan(0.8);
        }
    });

    it('tells the six designs apart by their proportions', () => {
        const box = Object.fromEntries(MODELS.hero.map((model) => [model.design, extents(model)]));
        // The splinter: long and thin either way.
        expect(box.splinter[2] / box.splinter[1]).toBeGreaterThan(2.2);
        // The slab: thin one way, broad the other two.
        expect(box.slab[0] / box.slab[1]).toBeLessThan(0.45);
        // The binary and the potato: long, but with a body.
        expect(box.binary[2] / box.binary[0]).toBeGreaterThan(1.5);
        expect(box.potato[2] / box.potato[0]).toBeGreaterThan(1.5);
        // The block and the rubble: chunky, about as deep as they are broad.
        expect(box.block[2] / box.block[0]).toBeLessThan(1.5);
        expect(box.rubble[2] / box.rubble[0]).toBeLessThan(1.5);
        // Every level keeps the silhouette of its design.
        ['boulder', 'chip'].forEach((level) => MODELS[level].forEach((model) => {
            const hero = box[model.design];
            extents(model).forEach((e, k) => expect(Math.abs(e - hero[k])).toBeLessThan(0.12));
        }));
    });

    it('knows where light gets through: thin splinters and slabs, never the heart of the rubble', () => {
        const thin = Object.fromEntries(MODELS.hero.map((model) => [model.design, mean(channel(read(model), 2))]));
        expect(thin.splinter).toBeGreaterThan(0.6);
        expect(thin.slab).toBeGreaterThan(0.6);
        expect(thin.rubble).toBeLessThan(0.2);
        // The block is thick in its heart and thin at its broken edges.
        const block = channel(read(MODELS.hero[0]), 2);
        expect(Math.max(...block)).toBeGreaterThan(0.75);
        expect(Math.min(...block)).toBeLessThan(0.2);
    });

    it('merges a level into one mesh, every vertex tagged with the design it wears', () => {
        ROCK_LEVELS.forEach((level) => {
            const mesh = rockMesh(level);
            expect(rockMesh(level)).toBe(mesh);
            expect(mesh.variants).toBe(DESIGNS.length);
            expect(mesh.vertexCount).toBe(MODELS[level].reduce((sum, m) => sum + m.vertexCount, 0));
            expect(mesh.triangleCount).toBe(MODELS[level].reduce((sum, m) => sum + m.triangleCount, 0));
            // (Uint16 indices: the merged level must stay under 65536 vertices.)
            expect(mesh.vertexCount).toBeLessThan(65536);
            mesh.ranges.forEach((range, variant) => {
                expect(range.design).toBe(DESIGNS[variant]);
                for (let v = range.vertex; v < range.vertex + range.vertices; v++) {
                    expect(mesh.shade[v * 4 + 3]).toBe(variant);
                }
                // A model's triangles stay among its own vertices.
                for (let i = range.index; i < range.index + range.indices; i++) {
                    expect(mesh.index[i]).toBeGreaterThanOrEqual(range.vertex);
                    expect(mesh.index[i]).toBeLessThan(range.vertex + range.vertices);
                }
            });
            expect([...mesh.position, ...mesh.normal, ...mesh.shade].every(Number.isFinite)).toBe(true);
        });
    });

    it('is a modest module, generated by the Blender script', () => {
        const file = path.join(root, 'src/themes/stellar-drift/stellar-drift-rock-models.js');
        const source = readFileSync(file, 'utf8');
        expect(source).toMatch(/GENERATED by scripts\/blender\/stellar_drift_rocks\.py/);
        expect(source.length).toBeLessThan(200 * 1024);
        const script = readFileSync(path.join(root, 'scripts/blender/stellar_drift_rocks.py'), 'utf8');
        expect(script).toMatch(/stellar-drift-rock-models\.js/);
        // The theme stands on its own: nothing of another theme's is read.
        expect(script).not.toMatch(/void_ember|void-ember/);
        const rocks = readFileSync(path.join(root, 'src/themes/stellar-drift/stellar-drift-rocks.js'), 'utf8');
        expect(rocks).not.toMatch(/from '\.\.\/(?!shared\/)[^']*'/);
    });
});
